  'Text size, font and sound effects': { de: 'Textgröße, Schrift und Geräusche', fr: 'Taille du texte, police et effets sonores', es: 'Tamaño del texto, letra y efectos de sonido', ja: 'もじの おおきさ・ほんの もじ・こうかおん' },
  'Recording yourself reading': { de: 'Dich selbst beim Vorlesen aufnehmen', fr: 'Vous enregistrer en train de lire', es: 'Grabarte leyendo', ja: '自分の声でろくおんする' },
  'Making your own book': { de: 'Dein eigenes Buch machen', fr: 'Créer votre propre livre', es: 'Hacer tu propio libro', ja: '自分の本をつくる' },
